    let members: Vec<Vec<&str>> = data
        .interfaces
        .iter()
        .filter(|(key, _)| key.ends_with(":Props"))
        .map(|(_, iface)| iface.props.iter().map(|p| p.name.as_str()).collect())
        .collect();
    assert_eq!(members, [["label"]]);
}

