fn check_atoms(check: &CollectedType, file: &Utf8Path, ctx: &ResolutionContext, depth: u8) -> Option<Vec<Atom>> {
    match check {
        CollectedType::AtFile { file, inner } => check_atoms(inner, file, ctx, depth + 1),
